oxy_webhelp_navlinks = {"arch_disaster_recovery_using_arch_loc-d39536e9648":{"topics":[{"title":"Reader-writer archiving model","shortdesc":"<p class=\"shortdesc\">The reader-writer archival model permits mapping a single owner Rubrik cluster to one     or more reader Rubrik clusters. This model increases the availability of archived data for     disaster recovery.<\/p>","href":"archival\/reader_writer_arch_model.html","attributes":{"data-id":"reader_writer_arch_model"},"menu":{"hasChildren":false},"tocID":"reader_writer_arch_model-d39536e9659","topics":[]},{"title":"Rubrik cluster owner role","shortdesc":"<p class=\"shortdesc\">Owner Rubrik clusters can pause, disable, and delete archival locations. The actions         available on a location vary depending on its current state.<\/p>","href":"archival\/arch_cluster_owner_role.html","attributes":{"data-id":"arch_cluster_owner_role"},"menu":{"hasChildren":false},"tocID":"arch_cluster_owner_role-d39536e9670","topics":[]},{"title":"Reader cluster and archival location connections","shortdesc":"<p class=\"shortdesc\">Connecting a reader Rubrik cluster to an archival location lets you recover         snapshot data from the archival location.<\/p>","href":"archival\/reader_cluster_arch_location_connections.html","attributes":{"data-id":"reader_cluster_arch_location_connections"},"menu":{"hasChildren":false},"tocID":"reader_cluster_arch_location_connections-d39536e9681","topics":[]},{"title":"Reader cluster workload refresh","shortdesc":"<p class=\"shortdesc\">Refreshing workloads on the reader Rubrik cluster synchronizes the recovery view of         the reader cluster with the contents of the archival location.<\/p>","href":"archival\/reader_cluster_workload_refresh_2.html","attributes":{"data-id":"reader_cluster_workload_refresh"},"menu":{"hasChildren":false},"tocID":"reader_cluster_workload_refresh-d39536e9692","topics":[]},{"title":"Archival reader and replication pair coexistence","shortdesc":"<p class=\"shortdesc\">A Rubrik cluster can serve as both an archival reader (also known as Archival DR) and         a replication target for the same workloads, without requiring separate clusters for each         function.<\/p>","href":"archival\/arch_archival_reader_repl_coexistence.html","attributes":{"data-id":"arch_archival_reader_repl_coexistence"},"menu":{"hasChildren":false},"tocID":"arch_archival_reader_repl_coexistence-d39536e9703","topics":[]},{"title":"Rubrik Cloud Vault reader location information","shortdesc":"<p class=\"shortdesc\">Information about the Rubrik Cloud Vault archival location settings to create a         location on the reader Rubrik cluster.<\/p>","href":"archival\/rcv_reader_location_info.html","attributes":{"data-id":"rcv_reader_location_info"},"menu":{"hasChildren":false},"tocID":"rcv_reader_location_info-d39536e9714","topics":[]}]}};